mapper.update:
merge into T_SAP_STOCK a USING (
select #{Item.stockDate,jdbcType=DATE} stock_date, #{Item.sapCode,jdbcType=VARCHAR} sap_code, #{Item.stockNum,jdbcType=DECIMAL} stock_num, #{Item.remark,jdbcType=VARCHAR} remark, #{Item.createBy,jdbcType=VARCHAR} create_by, #{Item.createTime,jdbcType=DATE} create_time, #{Item.updateTime,jdbcType=DATE} update_time from dual
) b ON ( ((b.stock_date is null and a.stock_date is null) or (a.stock_date = b.stock_date)) AND a.sap_code = b.sap_code AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.stock_num = b.stock_num, a.update_by = b.create_by, a.update_time = now(), a.remark = b.remark WHEN NOT MATCHED THEN INSERT (a.id, a.stock_date, a.sap_code, a.stock_num, a.create_by, a.create_time, a.remark, a.del_flag) values (SEQ_T_SAP_STOCK.NEXTVAL, b.stock_date, b.sap_code, b.stock_num, b.create_by, now(), b.remark, 0)
